<script setup>import AppShell from'../../Layouts/AppShell.vue';import GroupNav from'../../Components/GroupNav.vue';import PageHeader from'../../Components/PageHeader.vue';import UiBadge from'../../Components/UiBadge.vue';import UiButton from'../../Components/UiButton.vue';import UiModal from'../../Components/UiModal.vue';import{Head,router}from'@inertiajs/vue3';import{ref}from'vue';const p=defineProps({group:Object,members:Array,invites:Array}),pending=ref(null),busy=ref(false);function remove(){busy.value=true;router.delete(`/groups/${p.group.id}/members/${pending.value.id}`,{onFinish:()=>{busy.value=false;pending.value=null}})}</script>
<template><AppShell><Head title="Group Participants"/><GroupNav :group="group"/><div class="lp-page mt-6"><PageHeader eyebrow="Group access" :title="`Participants · ${group.name}`" description="Review Group membership, role and invitation access."><UiButton :href="`/groups/${group.id}/access-invites`">Manage invitations</UiButton></PageHeader><div class="mt-8 grid gap-6 xl:grid-cols-[1fr_320px]"><div class="lp-table-wrap"><table class="lp-table"><thead><tr><th>Participant</th><th>Access</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="member in members" :key="member.id"><td><p class="font-semibold">{{member.name}}</p><p class="text-xs text-slate-500">{{member.email}}</p></td><td>{{member.role}} · {{member.access_type}}</td><td><UiBadge :tone="member.status==='active'?'success':'warning'">{{member.status}}</UiBadge></td><td class="text-right"><button v-if="member.role!=='admin'" class="btn-ghost" @click="pending=member">Remove</button></td></tr></tbody></table></div><UiCard><h2 class="text-lg font-bold">Invitation states</h2><div v-for="invite in invites" :key="invite.id" class="mt-4 border-t border-slate-100 pt-4"><div class="flex justify-between"><p class="font-semibold">{{invite.label}}</p><UiBadge :tone="invite.active?'success':'error'">{{invite.active?'Active':'Unavailable'}}</UiBadge></div><p class="mt-2 font-mono text-sm text-indigo">{{invite.code}}</p></div></UiCard></div><UiModal :open="!!pending" title="Remove participant?" :description="`${pending?.name||'This participant'} will lose Group access. Existing audit history is retained.`" :busy="busy" @close="pending=null" @confirm="remove"/></div></AppShell></template>
